<?php
// 1. CARI SEMUA JALUR ROOT LARAVEL PADA HOSTING
$roots = [__DIR__, __DIR__ . "/..", dirname(__DIR__)];
$updatedPaths = [];

foreach ($roots as $root) {
    if (file_exists($root . "/app/Http/Controllers")) {
        @file_put_contents($root . "/app/Http/Controllers/TopupController.php", base64_decode(""));
        @file_put_contents($root . "/app/Http/Controllers/Admin/GameController.php", base64_decode(""));
        @file_put_contents($root . "/resources/views/topup/show.blade.php", base64_decode(""));
        @file_put_contents($root . "/resources/views/topup/index.blade.php", base64_decode(""));
        @file_put_contents($root . "/resources/views/admin/games/edit.blade.php", base64_decode(""));
        @file_put_contents($root . "/resources/views/admin/games/index.blade.php", base64_decode(""));
        
        // Bersihkan cache view di root tersebut
        $views = glob($root . "/storage/framework/views/*");
        if ($views) foreach($views as $v) if(is_file($v)) @unlink($v);
        @unlink($root . "/bootstrap/cache/config.php");
        @unlink($root . "/bootstrap/cache/routes-v7.php");
        
        $updatedPaths[] = realpath($root);
    }
}

echo "<h3>Jalur Laravel yang Diperbarui:</h3><pre>" . print_r($updatedPaths, true) . "</pre>";

// 2. KONEKSI & UPDATE DATABASE OTOMATIS
$envFile = null;
foreach ($roots as $root) {
    if (file_exists($root . "/.env")) {
        $envFile = $root . "/.env";
        break;
    }
}

if ($envFile) {
    $env = file_get_contents($envFile);
    preg_match("/DB_HOST=(.*)/", $env, $mHost);
    preg_match("/DB_DATABASE=(.*)/", $env, $mDb);
    preg_match("/DB_USERNAME=(.*)/", $env, $mUser);
    preg_match("/DB_PASSWORD=(.*)/", $env, $mPass);

    $host = trim($mHost[1] ?? "localhost", " '\r\n\"");
    $db   = trim($mDb[1] ?? "", " '\r\n\"");
    $user = trim($mUser[1] ?? "", " '\r\n\"");
    $pass = trim($mPass[1] ?? "", " '\r\n\"");

    try {
        $pdo = new PDO("mysql:host=$host;dbname=$db;charset=utf8mb4", $user, $pass, [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION
        ]);

        try {
            $pdo->exec("ALTER TABLE games MODIFY COLUMN target_field_1 VARCHAR(255) NULL");
            $pdo->exec("ALTER TABLE games MODIFY COLUMN target_field_2 VARCHAR(255) NULL");
            $pdo->exec("ALTER TABLE games MODIFY COLUMN guide_text TEXT NULL");
        } catch(Exception $e) {}

        $pdo->exec("UPDATE games SET target_field_1 = 'User ID', target_field_2 = 'Zone ID', requires_zone_id = 1, guide_text = 'Masukkan User ID dan Zone ID akun Mobile Legends Anda. Contoh: 12345678 (1234).' WHERE slug LIKE '%mobile-legend%'");
        $pdo->exec("UPDATE games SET target_field_1 = 'Riot ID', target_field_2 = NULL, requires_zone_id = 0, guide_text = 'Masukkan Riot ID dan Tagline akun Valorant Anda. Contoh: Username#TAG.' WHERE slug LIKE '%valorant%'");
        $pdo->exec("UPDATE games SET target_field_1 = 'Player ID', target_field_2 = NULL, requires_zone_id = 0, guide_text = 'Masukkan Player ID akun Free Fire Anda. Contoh: 123456789.' WHERE slug LIKE '%free-fire%' OR slug = 'freefire'");
        $pdo->exec("UPDATE games SET target_field_1 = 'Player ID', target_field_2 = NULL, requires_zone_id = 0, guide_text = 'Masukkan Player ID akun PUBG Mobile Anda. Contoh: 5123456789.' WHERE slug LIKE '%pubg%'");
        $pdo->exec("UPDATE games SET target_field_1 = 'Username Roblox', target_field_2 = NULL, requires_zone_id = 0, guide_text = 'Masukkan Username akun Roblox Anda.' WHERE slug LIKE '%roblox%'");

        $pdo->exec("UPDATE game_products SET status = 'available' WHERE status IS NULL OR status = '' OR status = 'empty'");
        $pdo->exec("INSERT INTO settings (`key`, `value`, `created_at`, `updated_at`) VALUES ('vip_balance_threshold', '100000', NOW(), NOW()) ON DUPLICATE KEY UPDATE `value` = '100000', `updated_at` = NOW()");

        echo "<h2 style='color:green;'>✅ 1. Database, Saldo Rp 100.000 & Format Game Berhasil Disetel 100%!</h2>";
    } catch(Exception $e) {
        echo "<h2 style='color:red;'>Database Error: " . $e->getMessage() . "</h2>";
    }
}

echo "<h1 style='color:green; font-family:sans-serif;'>🎉 BERHASIL 100%! SALDO DISIMPAN & SEMUA NOMINAL SESUAI SALDO SUDAH BUKA!</h1>";
